// RecordNutanixVolumeGroupCountDataPoint adds a data point to nutanix.volume_group.count metric.
func (mb *MetricsBuilder) RecordNutanixVolumeGroupCountDataPoint(ts pcommon.Timestamp, val float64, nutanixClusterIDAttributeValue string, nutanixClusterNameAttributeValue string) {
	mb.metricNutanixVolumeGroupCount.recordDataPoint(mb.startTime, ts, val, nutanixClusterIDAttributeValue, nutanixClusterNameAttributeValue)
}

// RecordNutanixVolumeGroupStatDataPoint adds a data point to nutanix.volume_group.stat metric.
func (mb *MetricsBuilder) RecordNutanixVolumeGroupStatDataPoint(ts pcommon.Timestamp, val float64, nutanixVolumeGroupIDAttributeValue string, nutanixVolumeGroupNameAttributeValue string, nutanixClusterIDAttributeValue string, nutanixStatNameAttributeValue string, nutanixStatKindAttributeValue AttributeNutanixStatKind) {
	mb.metricNutanixVolumeGroupStat.recordDataPoint(mb.startTime, ts, val, nutanixVolumeGroupIDAttributeValue, nutanixVolumeGroupNameAttributeValue, nutanixClusterIDAttributeValue, nutanixStatNameAttributeValue, nutanixStatKindAttributeValue.String())
}

// Reset resets metrics builder to its initial state. It should be used when external metrics source is restarted,
// and metrics builder should update its startTime and reset it's internal state accordingly.
func (mb *MetricsBuilder) Reset(options ...MetricBuilderOption) {
	mb.startTime = pcommon.NewTimestampFromTime(time.Now())
	for _, op := range options {
		op.apply(mb)
	}
}
